                        onClick={handleConnectPrinter}
                        disabled={isConnectingPrinter || isPrinterConnected}
                        className={`text-xs flex items-center gap-1 px-3 py-1.5 rounded-full transition-colors ${isPrinterConnected ? 'bg-green-100 text-green-700' : 'bg-blue-50 text-blue-600 hover:bg-blue-100 border border-blue-200'}`}
